def rollback(reason: str):
    print(f"\nROLLBACK: {reason}")
    for p, b in backups.items():
        shutil.copy2(b, p)
    if os.path.exists(P_TEST):
        os.remove(P_TEST)
    for p, b in backups.items():
        os.remove(b)
    die("rolled back; primary tree restored byte-for-byte, no backups left behind")


